--
-- Table structure for table `reuniones_historial`
--

DROP TABLE IF EXISTS `reuniones_historial`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reuniones_historial` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `congregacion_id` bigint unsigned NOT NULL,
  `publicador_id` bigint unsigned NOT NULL,
  `programa_id` bigint unsigned NOT NULL,
  `fecha_semana` date NOT NULL,
  `tipo_parte` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rol` enum('principal','ayudante') COLLATE utf8mb4_unicode_ci NOT NULL,
  `es_emergencia` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `reuniones_historial_publicador_id_foreign` (`publicador_id`),
  KEY `reuniones_historial_programa_id_foreign` (`programa_id`),
  KEY `rh_cong_pub_fecha_idx` (`congregacion_id`,`publicador_id`,`fecha_semana`),
  CONSTRAINT `reuniones_historial_congregacion_id_foreign` FOREIGN KEY (`congregacion_id`) REFERENCES `congregaciones` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reuniones_historial_programa_id_foreign` FOREIGN KEY (`programa_id`) REFERENCES `reuniones_programas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reuniones_historial_publicador_id_foreign` FOREIGN KEY (`publicador_id`) REFERENCES `publicadores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1560 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

