--
-- Table structure for table `turno_asignaciones`
--

DROP TABLE IF EXISTS `turno_asignaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `turno_asignaciones` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `turno_id` bigint unsigned NOT NULL,
  `turno_generado_id` bigint unsigned DEFAULT NULL,
  `publicador_id` bigint unsigned NOT NULL,
  `fecha` date NOT NULL,
  `rol` enum('capitan','voluntario') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'voluntario',
  `estado` enum('pendiente','confirmado','completado','cancelado') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `notas` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `asignacion_unique` (`turno_id`,`publicador_id`,`fecha`),
  KEY `turno_asignaciones_publicador_id_foreign` (`publicador_id`),
  KEY `turno_asignaciones_turno_generado_id_foreign` (`turno_generado_id`),
  CONSTRAINT `turno_asignaciones_publicador_id_foreign` FOREIGN KEY (`publicador_id`) REFERENCES `publicadores` (`id`) ON DELETE CASCADE,
  CONSTRAINT `turno_asignaciones_turno_generado_id_foreign` FOREIGN KEY (`turno_generado_id`) REFERENCES `turnos_generados` (`id`) ON DELETE CASCADE,
  CONSTRAINT `turno_asignaciones_turno_id_foreign` FOREIGN KEY (`turno_id`) REFERENCES `turnos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2327 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

